class Solution {
  public int countCornerRectangles(int[][] grid) {
    int m = grid.length, n = grid[0].length, total = 0;
    // for each pair of rows, any two shared 1-columns form a rectangle
    for (int a = 0; a < m; a++)
      for (int b = a + 1; b < m; b++) {
        int shared = 0;
        for (int c = 0; c < n; c++) if (grid[a][c] == 1 && grid[b][c] == 1) shared++;
        total += shared * (shared - 1) / 2;
      }
    return total;
  }
}
